#!/usr/bin/env python3
"""Keep Claude Code's and GitHub Copilot's generated files in step with the shared sources.

  CLAUDE.md                          -> .github/copilot-instructions.md      (copy)
  <skill dir>/SKILL.md               -> .github/prompts/<name>.prompt.md     (Copilot slash command for the skill)
  <skill dir>                        -> .claude/skills/<name>, .github/skills/<name>        (symlink)
  agents/**/<name>.agent.md          -> .claude/agents/<name>.agent.md, .github/agents/...  (symlink)

Skill dirs are skills/<name>/ (shared skills) and agents/<agent>/skills/<name>/ (skills that belong to one
agent, kept next to its .agent.md). Agents are *.agent.md files anywhere under agents/.

Only those exact files and folders are linked, so neither tool loads an agent's skills as agents,
and agent-owned skills never need a copy or link in the root skills/ folder.

Usage: python3 scripts/sync-copilot.py [--check]
  --check  change nothing; exit 1 if any generated file or link is missing or out of date.
"""
import json, os, re, sys
from pathlib import Path

root = Path(__file__).resolve().parent.parent
check = "--check" in sys.argv[1:]
stale = []
GENERATED = "Generated by scripts/sync-copilot.py"


def write(path: Path, text: str) -> None:
    if path.exists() and path.read_text() == text:
        return
    stale.append(str(path.relative_to(root)))
    if not check:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text)


def frontmatter(md: str) -> dict:
    m = re.match(r"^---\n(.*?)\n---\n", md, re.S)
    out = {}
    for line in (m.group(1) if m else "").splitlines():
        k, sep, v = line.partition(":")
        if sep and not line.startswith((" ", "\t")):
            out[k.strip()] = v.strip().strip('"').strip("'")
    return out


def unique(items: dict, kind: str) -> None:
    """items: name -> list of sources. Stop if two sources share a name."""
    clashes = {n: s for n, s in items.items() if len(s) > 1}
    if clashes:
        lines = [f"  {n}: " + ", ".join(str(p.relative_to(root)) for p in s) for n, s in sorted(clashes.items())]
        sys.exit(f"Two {kind} share a name; rename one:\n" + "\n".join(lines))


def sync_links(link_dir: Path, targets: dict) -> None:
    """Make link_dir a real folder holding exactly one symlink per name -> target path."""
    rel_dir = link_dir.relative_to(root)
    if link_dir.is_symlink():  # the old layout linked a whole folder
        stale.append(f"{rel_dir} (folder link replaced by per-item links)")
        if check:
            return
        link_dir.unlink()
    if not check:
        link_dir.mkdir(parents=True, exist_ok=True)
    for name, target_path in sorted(targets.items()):
        target = os.path.relpath(target_path, link_dir)
        link = link_dir / name
        if link.is_symlink() and os.readlink(link) == target:
            continue
        stale.append(f"{rel_dir}/{name}")
        if not check:
            if link.is_symlink() or link.is_file():
                link.unlink()
            elif link.exists():
                sys.exit(f"{rel_dir}/{name} is a real folder, not a link; move it into skills/ or agents/ first.")
            link.symlink_to(target)
    if link_dir.is_dir() and not link_dir.is_symlink():
        for p in link_dir.iterdir():
            if p.name not in targets and p.is_symlink():
                stale.append(f"{rel_dir}/{p.name} (removed)")
                if not check:
                    p.unlink()


# --- Discover skills and agents -------------------------------------------------------------------
skill_sources = {}
for skill_md in sorted(list((root / "skills").glob("*/SKILL.md")) + list((root / "agents").glob("*/skills/*/SKILL.md"))):
    d = skill_md.parent
    if d.is_symlink():  # leftover links in skills/ from the old layout are not sources
        continue
    name = frontmatter(skill_md.read_text()).get("name") or d.name
    skill_sources.setdefault(name, []).append(d)
unique(skill_sources, "skills")
skills = {n: s[0] for n, s in skill_sources.items()}

agent_sources = {}
for f in sorted((root / "agents").rglob("*.agent.md")):
    agent_sources.setdefault(f.name, []).append(f)
unique(agent_sources, "agents")
agents = {n: s[0] for n, s in agent_sources.items()}

# --- 1. Instructions ------------------------------------------------------------------------------
write(root / ".github/copilot-instructions.md", (root / "CLAUDE.md").read_text())

# --- 2. Copilot prompt files, one per skill ---------------------------------------------------------
prompts = root / ".github/prompts"
for name, d in sorted(skills.items()):
    src = d.relative_to(root)
    desc = frontmatter((d / "SKILL.md").read_text()).get("description", f"Run the {name} skill")
    write(prompts / f"{name}.prompt.md", f"""---
description: {json.dumps(desc)}
agent: agent
---
<!-- {GENERATED} from {src}/SKILL.md. Don't edit; edit the skill and rerun. -->

Use the **{name}** skill: read [SKILL.md](../../{src}/SKILL.md) and follow it exactly, applying it to the request that follows this command. Run any scripts it mentions from the repository root.
""")
for p in prompts.glob("*.prompt.md") if prompts.exists() else []:
    if p.stem.removesuffix(".prompt") not in skills and GENERATED in p.read_text():
        stale.append(f"{p.relative_to(root)} (removed)")
        if not check:
            p.unlink()

# --- 3. Skill and agent links for both tools ----------------------------------------------------------
for tool in (".claude", ".github"):
    sync_links(root / tool / "skills", skills)
    sync_links(root / tool / "agents", agents)

if stale:
    print(("Out of date:" if check else "Updated:"), *stale, sep="\n  ")
else:
    print("Claude Code and Copilot files are up to date.")
sys.exit(1 if (check and stale) else 0)
